namespace BriefBar.Core.Presentation;

/// Each icon's drawings, from Fluent UI System Icons (MIT; windows/THIRD-PARTY-NOTICES.md): SVG paths on a square of
/// their size's units. Fluent draws each icon anew for each size, on that size's pixels, so an icon is sharp on as many
/// of a display's pixels as it was drawn for, and blurs scaled. BriefBar has each at the sizes it covers on a display,
/// where Fluent has them, all in one style, regular or filled, so that it looks the same at each.
public static class IconPaths
{
    /// The drawing of `icon` for an icon `size` pixels square on a display at `scale` (1 at 100%, 1.5 at 150%), so that
    /// it lines up with the display's pixels: the one Fluent made for as many pixels as it covers there, as 20 for a
    /// 16-pixel icon at 125%; else one made for half as many, doubled, as at 200%; else the nearest, the larger of two
    /// as near, scaled.
    public static IconPath Of(IconKey icon, double size, double scale)
    {
        var pixels = size * (double.IsFinite(scale) && scale > 0 ? scale : 1);
        var drawings = Drawings(icon: icon);
        return drawings.FirstOrDefault(predicate: drawing => Covers(drawing: drawing, pixels: pixels, times: 1))
            ?? drawings.FirstOrDefault(predicate: drawing => Covers(drawing: drawing, pixels: pixels, times: 2))
            ?? drawings.MinBy(keySelector: drawing => (Math.Abs(value: drawing.Size - pixels), -drawing.Size))!;
    }

    /// Every drawing of `icon` BriefBar has: its main one, and the others at the sizes it's also shown.
    public static IReadOnlyList<IconPath> Drawings(IconKey icon) => [Of(icon: icon), .. OtherSizes(icon: icon)];

